package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen0Test {

    private JsonWriter jsonWriter;
    private StringWriter stringWriter;

    @Before
    public void setUp() throws IOException {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValueTrue() throws IOException {
        jsonWriter.value(true);

        assertEquals("true", stringWriter.toString());
        ArgumentCaptor<String> captor = ArgumentCaptor.forClass(String.class);
        verify(jsonWriter).write(captor.capture());
        assertEquals("true", captor.getValue());
    }

    @Test
    public void testValueFalse() throws IOException {
        jsonWriter.value(false);

        assertEquals("false", stringWriter.toString());
        ArgumentCaptor<String> captor = ArgumentCaptor.forClass(String.class);
        verify(jsonWriter).write(captor.capture());
        assertEquals("false", captor.getValue());
    }

    @Test(expected = IOException.class)
    public void testValueThrowsIOException() throws IOException {
        doThrow(new IOException()).when(jsonWriter).beforeValue(false);
        jsonWriter.value(true);
    }

    @Test
    public void testValueReturnsSelf() throws IOException {
        JsonWriter writer = jsonWriter.value(true);
        assertSame(jsonWriter, writer);
    }

    @Test
    public void testWriteDeferredNameCalled() throws IOException {
        doNothing().when(jsonWriter).writeDeferredName();
        jsonWriter.value(true);
        verify(jsonWriter, times(1)).writeDeferredName();
    }

    @Test
    public void testBeforeValueCalled() throws IOException {
        doNothing().when(jsonWriter).beforeValue(false);
        jsonWriter.value(true);
        verify(jsonWriter, times(1)).beforeValue(false);
    }
}
